                SgAdd(scr, emon.Port.CellsAt(sgc, c + 12), emon.Port.CellsAt(sgc, c + 6), emon.Port.CellsAt(sgc, c + 1), emon.Port.CellsAt(sgc, c + 2), emon.Port.CellsAt(sgc, c + 3), emon.Port.CellsAt(sgc, c + 4), r0, rl, emon.Port.CellsAt(sgc, c + 7), fl + (65536 * emon.Port.CellsAt(sgc, c + 13)));
                total += 1;
            }
            k += 1;
        }
        row = 0;
        while (row < na) {
            c = row * 38;
            if ((emon.Port.CellsAt(an, c + 1) == Pdfannot.AnDigsig()) && (((emon.Port.CellsAt(an, c) + 1) == page) && (total < 64))) {
                start = emon.Port.CellsLen(et);
                SgDigitalText(et, an, txt, row);
                fl = 0;
                if ((emon.Port.CellsAt(an, c + 30) & 1) != 0) {
                    fl = 512;
                }
                SgAdd(scr, 5, row, emon.Port.CellsAt(an, c + 4), emon.Port.CellsAt(an, c + 5), emon.Port.CellsAt(an, c + 6), emon.Port.CellsAt(an, c + 7), start, emon.Port.CellsLen(et) - start, -1, fl + (65536 * (900 + (fl / 10))));
                total += 1;
            }
            row += 1;
        }
        return total;
    }
    public static int SgHasDigital(emon.Port.Cells an) {
        // 1 when `an` holds a synthetic digital signature row (P3.8's, D426): the document has a signature field with a widget on a page and so is a document with a seal node to write.
        int na = emon.Port.CellsLen(an) / 38;
        int i = 0;
        while (i < na) {
            if (emon.Port.CellsAt(an, (i * 38) + 1) == Pdfannot.AnDigsig()) {
                return 1;
            }
            i += 1;
        }
        return 0;
    }
